class Solution {
    public int reverse(int x) {
        boolean negative = x < 0;
        if (x > 0) {
            x = -x;
        }
        int result = 0;
        int lastAllowed = negative ? -8 : -7;

        while (x != 0) {
            // Java's remainder keeps the dividend's sign.
            int digit = x % 10;
            x /= 10;
            // Guard the update before it can overflow.
            if (result < -214748364 ||
                (result == -214748364 && digit < lastAllowed)) {
                return 0;
            }
            result = result * 10 + digit;
        }

        return negative ? result : -result;
    }
}

