function reverse(x) {
    const negative = x < 0;
    if (x > 0) x = -x;
    let result = 0;
    const lastAllowed = negative ? -8 : -7;

    while (x !== 0) {
        const digit = x % 10;
        x = Math.trunc(x / 10);
        // Guard before updating; integer values stay within 32-bit bounds.
        if (result < -214748364 ||
            (result === -214748364 && digit < lastAllowed)) {
            return 0;
        }
        result = result * 10 + digit;
    }

    // Avoid returning JavaScript's negative zero.
    if (result === 0) return 0;
    return negative ? result : -result;
}
